CID = 'oop'
CLASS, INIT, METH, CLSATTR, MAGIC, INHERIT, POLY, ENCAP, CLSMETH = "Class vs object", "__init__ and self", "Attributes and methods", "Class attributes vs instance attributes", "Magic methods: __str__ and friends", "Inheritance: building on another class", "Polymorphism: same method name, different behaviour", "Encapsulation: protecting data", "Class methods and static methods"
def W(lv, sec, q, starter, sol, e): return dict(lv=lv, ty='code', sec=sec, q=q, starter=starter, sol=sol, e=e)
def F(lv, sec, q, c, fixed, e): return dict(lv=lv, ty='fix', sec=sec, q=q, c=c, fixed=fixed, e=e)
def T(lv, sec, c, e): return dict(lv=lv, ty='type', sec=sec, q="Type exactly what this code prints.", c=c, e=e)
Q = [
 # ---------- Basic ----------
 T(1, CLASS, 'class Room:\n    pass\n\nr1 = Room()\nr2 = Room()\nprint(type(r1).__name__, r1 is r2)', "A class is the blueprint and each call `Room()` makes a new, separate object, so `r1` and `r2` are not the same object."),
 W(1, INIT, 'Write a class `Product` whose `__init__(self, name, price)` stores both values. Create `Product("Pen", 10)` and print its name and price with one `print()`.', '# class Product:\n', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\np = Product("Pen", 10)\nprint(p.name, p.price)', "`__init__` runs when the object is created. `self.name = name` stores the value inside that object."),
 W(1, METH, 'Write a class `Circle` that stores a radius and has a method `area()` returning `round(3.14159 * radius ** 2, 2)`. Print `Circle(2).area()`.', '# class Circle:\n', 'class Circle:\n    def __init__(self, radius):\n        self.radius = radius\n\n    def area(self):\n        return round(3.14159 * self.radius ** 2, 2)\n\nprint(Circle(2).area())', "A method is a function inside the class. It reads the object\'s data through `self`."),
 W(1, METH, 'The starter has a `Student` class. Create `Student("Asha", 70)`, change its marks to 82, and print `Asha 82`.', 'class Student:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n', 'class Student:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n\ns = Student("Asha", 70)\ns.marks = 82\nprint(s.name, s.marks)', "Attributes are like variables that belong to one object. You can read and change them with a dot."),
 W(1, MAGIC, 'Give `Product` a `__str__` method so that `print(Product("Pen", 10))` prints `Pen: Rs 10`.', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\n    def __str__(self):\n        return f"{self.name}: Rs {self.price}"\n\nprint(Product("Pen", 10))', "`print()` calls `__str__` to get the text for an object. It must **return** a string."),
 F(1, INIT, "This code should print `Tata`, but it crashes. Fix it.", 'class Car:\n    def __init__(brand):\n        self.brand = brand\n\nc = Car("Tata")\nprint(c.brand)', 'class Car:\n    def __init__(self, brand):\n        self.brand = brand\n\nc = Car("Tata")\nprint(c.brand)', "Every method needs `self` as its first parameter. Python passes the object in automatically."),
 T(1, CLSATTR, 'class Student:\n    school = "WsCube"\n    def __init__(self, name):\n        self.name = name\n\na = Student("Asha")\nb = Student("Ravi")\nb.school = "Other"\nprint(a.school, b.school, Student.school)', "`b.school = ...` creates an instance attribute on `b` only. `a` and the class still share the class attribute."),
 F(1, METH, "This code should print `500`, but it crashes. Fix the method.", 'class Account:\n    def __init__(self, balance):\n        self.balance = balance\n\n    def show(self):\n        print(balance)\n\nAccount(500).show()', 'class Account:\n    def __init__(self, balance):\n        self.balance = balance\n\n    def show(self):\n        print(self.balance)\n\nAccount(500).show()', "Inside a method, the object\'s data is `self.balance`. A plain `balance` is an unknown local name."),
 # ---------- Medium ----------
 W(2, INHERIT, 'Write `Person` with `introduce()` returning `"Hi, I am <name>"`. Write `Employee(Person)` that also stores a company and overrides `introduce()` to add `" from <company>"`, using `super().introduce()`. Print `Employee("Asha", "TCS").introduce()`.', '# class Person:\n# class Employee(Person):\n', 'class Person:\n    def __init__(self, name):\n        self.name = name\n\n    def introduce(self):\n        return f"Hi, I am {self.name}"\n\nclass Employee(Person):\n    def __init__(self, name, company):\n        super().__init__(name)\n        self.company = company\n\n    def introduce(self):\n        return super().introduce() + f" from {self.company}"\n\nprint(Employee("Asha", "TCS").introduce())', "The child class reuses the parent\'s code with `super()` and only adds what is new."),
 W(2, POLY, 'Write classes `Circle(r)` and `Square(side)`, each with an `area()` method (circle: `round(3.14159 * r ** 2, 2)`). Loop over `[Circle(1), Square(3)]` and print each area.', '# class Circle:\n# class Square:\n', 'class Circle:\n    def __init__(self, r):\n        self.r = r\n\n    def area(self):\n        return round(3.14159 * self.r ** 2, 2)\n\nclass Square:\n    def __init__(self, side):\n        self.side = side\n\n    def area(self):\n        return self.side * self.side\n\nfor shape in [Circle(1), Square(3)]:\n    print(shape.area())', "Polymorphism: the loop calls `area()` on every shape without caring which class it is. Each class does its own maths."),
 T(2, INHERIT, 'class A:\n    def hello(self):\n        return "A"\n\nclass B(A):\n    pass\n\nclass C(A):\n    def hello(self):\n        return "C"\n\nprint(B().hello(), C().hello(), isinstance(C(), A))', "`B` inherits `hello()` from `A`. `C` overrides it. A `C` object is still an `A`, so `isinstance` is `True`."),
 W(2, ENCAP, 'Write `BankAccount` with a private `__balance`, a `deposit(amount)` that raises `ValueError("Deposit must be positive")` for 0 or less, and `get_balance()`. Deposit 500, then try to deposit -50 (catch it and print the message), then print the balance.', '# class BankAccount:\n', 'class BankAccount:\n    def __init__(self, balance=0):\n        self.__balance = balance\n\n    def deposit(self, amount):\n        if amount <= 0:\n            raise ValueError("Deposit must be positive")\n        self.__balance += amount\n\n    def get_balance(self):\n        return self.__balance\n\nacc = BankAccount()\nacc.deposit(500)\ntry:\n    acc.deposit(-50)\nexcept ValueError as e:\n    print(e)\nprint(acc.get_balance())', "The balance can only change through `deposit()`, which checks the amount first. That is encapsulation."),
 W(2, MAGIC, 'Give `Product` an `__eq__` method so two products are equal when their prices are equal. Print `Product("Pen", 10) == Product("Pencil", 10)`.', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\n    def __eq__(self, other):\n        return self.price == other.price\n\nprint(Product("Pen", 10) == Product("Pencil", 10))', "`a == b` calls `a.__eq__(b)`. Without it, two different objects are never equal."),
 F(2, MAGIC, "This code should print `Item: Pen` once, but it crashes. Fix `__str__`.", 'class Item:\n    def __init__(self, name):\n        self.name = name\n\n    def __str__(self):\n        print("Item:", self.name)\n\nprint(Item("Pen"))', 'class Item:\n    def __init__(self, name):\n        self.name = name\n\n    def __str__(self):\n        return f"Item: {self.name}"\n\nprint(Item("Pen"))', "`__str__` must **return** the text. Printing inside it returns `None`, and `print()` then fails."),
 W(2, CLSATTR, 'Write `Booking` with a class attribute `count = 0` that goes up by 1 every time a booking is created. Create 3 bookings and print `Booking.count`.', '# class Booking:\n', 'class Booking:\n    count = 0\n\n    def __init__(self, guest):\n        self.guest = guest\n        Booking.count += 1\n\nBooking("Asha")\nBooking("Ravi")\nBooking("Neha")\nprint(Booking.count)', "A class attribute is shared by all objects. Change it through the class name, `Booking.count`."),
 W(2, CLSMETH, 'Write `Booking(guest, amount)` with a class method `from_text(cls, text)` that makes a booking from text like `"Asha,4500"` (amount as an int). Create one with `Booking.from_text("Asha,4500")` and print its guest and amount.', '# class Booking:\n', 'class Booking:\n    def __init__(self, guest, amount):\n        self.guest = guest\n        self.amount = amount\n\n    @classmethod\n    def from_text(cls, text):\n        guest, amount = text.split(",")\n        return cls(guest, int(amount))\n\nb = Booking.from_text("Asha,4500")\nprint(b.guest, b.amount)', "A class method gets the class as `cls`, so it can build and return a new object: another way to create one."),
 T(2, ENCAP, 'class Room:\n    def __init__(self, rate):\n        self._rate = rate\n\n    @property\n    def rate(self):\n        return self._rate\n\n    @rate.setter\n    def rate(self, value):\n        if value < 0:\n            raise ValueError("Rate cannot be negative")\n        self._rate = value\n\nr = Room(2000)\nr.rate = 2500\ntry:\n    r.rate = -5\nexcept ValueError as e:\n    print(e)\nprint(r.rate)', "The setter runs on every `r.rate = ...`. It accepts 2500 and rejects -5, so the rate stays 2500."),
 F(2, INHERIT, "This code should print `Asha 90`, but it crashes. Fix `Student.__init__`.", 'class Person:\n    def __init__(self, name):\n        self.name = name\n\nclass Student(Person):\n    def __init__(self, name, marks):\n        self.marks = marks\n\ns = Student("Asha", 90)\nprint(s.name, s.marks)', 'class Person:\n    def __init__(self, name):\n        self.name = name\n\nclass Student(Person):\n    def __init__(self, name, marks):\n        super().__init__(name)\n        self.marks = marks\n\ns = Student("Asha", 90)\nprint(s.name, s.marks)', "When a child class has its own `__init__`, the parent\'s `__init__` does not run unless you call `super().__init__(...)`."),
 # ---------- Challenge (same chapter, combined) ----------
 W(3, MAGIC, 'Give `Product` a `__lt__` method that compares prices, so `sorted()` works on products. Sort `[Product("Pen", 10), Product("Bag", 450), Product("Ink", 45)]` and print the list of names, cheapest first.', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n', 'class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n\n    def __lt__(self, other):\n        return self.price < other.price\n\nitems = sorted([Product("Pen", 10), Product("Bag", 450), Product("Ink", 45)])\nprint([p.name for p in items])', "`sorted()` compares objects with `<`, which calls `__lt__`. Now your own objects can be sorted."),
 W(3, POLY, 'Write `Employee(name, salary)` with `pay()` returning the salary. `Manager(Employee)` also has a bonus and `pay()` returns salary + bonus. `Intern(name, stipend)` has `pay()` returning the stipend. Print the total of `pay()` for `[Employee("Asha", 40000), Manager("Ravi", 60000, 15000), Intern("Neha", 12000)]`.', '# class Employee:\n# class Manager(Employee):\n# class Intern:\n', 'class Employee:\n    def __init__(self, name, salary):\n        self.name = name\n        self.salary = salary\n\n    def pay(self):\n        return self.salary\n\nclass Manager(Employee):\n    def __init__(self, name, salary, bonus):\n        super().__init__(name, salary)\n        self.bonus = bonus\n\n    def pay(self):\n        return super().pay() + self.bonus\n\nclass Intern:\n    def __init__(self, name, stipend):\n        self.name = name\n        self.stipend = stipend\n\n    def pay(self):\n        return self.stipend\n\nstaff = [Employee("Asha", 40000), Manager("Ravi", 60000, 15000), Intern("Neha", 12000)]\nprint(sum(person.pay() for person in staff))', "Every class answers `pay()` in its own way, so one line can add up the whole payroll."),
 W(3, METH, 'Write a `Cart` class: `add(item, price, qty=1)` stores a line, `total()` returns the sum of price × qty, and `count()` returns the number of units. Add `("Pen", 10, 3)` and `("Bag", 450)`, then print the total and the count.', '# class Cart:\n', 'class Cart:\n    def __init__(self):\n        self.lines = []\n\n    def add(self, item, price, qty=1):\n        self.lines.append((item, price, qty))\n\n    def total(self):\n        return sum(price * qty for item, price, qty in self.lines)\n\n    def count(self):\n        return sum(qty for item, price, qty in self.lines)\n\ncart = Cart()\ncart.add("Pen", 10, 3)\ncart.add("Bag", 450)\nprint(cart.total(), cart.count())', "The object keeps its own list of lines, and the methods work on that list."),
 T(3, MAGIC, 'class Team:\n    def __init__(self, *names):\n        self.names = list(names)\n\n    def __len__(self):\n        return len(self.names)\n\n    def __contains__(self, name):\n        return name in self.names\n\nt = Team("Asha", "Ravi")\nprint(len(t), "Ravi" in t, "Neha" in t)', "`len(t)` calls `__len__` and `x in t` calls `__contains__`, so your object works like a built-in collection."),
 F(3, CLSATTR, "Each basket should have its own items, so this code should print `[]`. Fix it.", 'class Basket:\n    items = []\n\n    def add(self, x):\n        self.items.append(x)\n\na = Basket()\nb = Basket()\na.add("apple")\nprint(b.items)', 'class Basket:\n    def __init__(self):\n        self.items = []\n\n    def add(self, x):\n        self.items.append(x)\n\na = Basket()\nb = Basket()\na.add("apple")\nprint(b.items)', "A list made as a class attribute is shared by every basket. Make a new list per object in `__init__`."),
 W(3, CLSMETH, 'Write a class `GST` with a static method `add(amount, rate=18)` that returns the amount plus GST, rounded to 2 decimals. Print `GST.add(1000)` and `GST.add(250, 5)` with one `print()`.', '# class GST:\n', 'class GST:\n    @staticmethod\n    def add(amount, rate=18):\n        return round(amount + amount * rate / 100, 2)\n\nprint(GST.add(1000), GST.add(250, 5))', "A static method needs no object and no `self`. It is a plain function kept inside the class it belongs to."),
 W(3, METH, '`rows = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]`. Write `Student(name, marks)` with `grade()` returning `"A"` for 75 or more, else `"B"`. Make the objects with a list comprehension and print the names of the A-grade students.', 'rows = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]\n', 'rows = [("Asha", 82), ("Ravi", 67), ("Neha", 91)]\n\nclass Student:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n\n    def grade(self):\n        return "A" if self.marks >= 75 else "B"\n\nstudents = [Student(name, marks) for name, marks in rows]\nprint([s.name for s in students if s.grade() == "A"])', "Turning rows of data into objects lets every record carry its own logic, like `grade()`."),
]
